mapper.insert:
INSERT INTO PRJ_WRK_TM_CRTR_INFO_TBL (
	WRK_TM_CRTR_CD
  , 	WRK_TM_MEAS_CRTR_TP
  , USE_YN
  , WRK_TM_MEAS_CRTR_NM
  , WRK_TM_MEAS_CRTR_DGR
  , WRK_TM_MEAS_CRTR_VAL
  , WRK_TM_MEAS_CRTR_DESC
  , RGST_DT
  , RGST_SEQ
  , RGST_NM
)
VALUES (
	#{wrkTmCrtrCd, jdbcType=VARCHAR}
  , #{wrkTmMeasCrtrTp, jdbcType=VARCHAR}
  , 	(
		CASE
			WHEN (#{useYn, jdbcType=VARCHAR} IS NULL OR #{useYn, jdbcType=VARCHAR} = '') THEN 'Y'
			ELSE #{useYn, jdbcType=VARCHAR}
		END
  	)
  , 	#{wrkTmMeasCrtrNm, jdbcType=VARCHAR}
  , #{wrkTmMeasCrtrDgr, jdbcType=NUMERIC}
  , #{wrkTmMeasCrtrVal, jdbcType=NUMERIC}
  , #{wrkTmMeasCrtrDesc, jdbcType=VARCHAR}
  , CURRENT_TIMESTAMP(3)
  , #{rgstSeq, jdbcType=NUMERIC}
  , #{rgstNm, jdbcType=VARCHAR}
)
